<?php
require_once 'app.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??'';
    if($action==='create'){
        $name=trim($_POST['expense_category_name']??''); $amount=(float)($_POST['amount']??0);
        if($name===''||$amount<0){flash('error','Enter a valid category name and budget.');redirect('expense_category.php#add-category');}
        $stmt=mysqli_prepare($con,'INSERT INTO expense_category_tbl(expense_category_name,created_at,amount) VALUES(?,?,?)'); $date=date('Y-m-d'); mysqli_stmt_bind_param($stmt,'ssd',$name,$date,$amount);
        if(mysqli_stmt_execute($stmt)) flash('success','Budget category created successfully.'); else flash('error','Category already exists or could not be created.'); redirect('expense_category.php');
    }
    if($action==='update'){
        $id=(int)$_POST['id'];$name=trim($_POST['expense_category_name']??'');$amount=(float)($_POST['amount']??0);
        $stmt=mysqli_prepare($con,'UPDATE expense_category_tbl SET expense_category_name=?,amount=? WHERE expense_category_id=?');mysqli_stmt_bind_param($stmt,'sdi',$name,$amount,$id);mysqli_stmt_execute($stmt);flash('success','Budget updated.');redirect('expense_category.php');
    }
}
$rows=category_rows($con);render_header('Budgets & Categories','expense_category.php');
?>
<div class="page-head"><div><div class="eyebrow">Planning</div><h1>Budgets & categories</h1><p>Define spending limits and monitor how much each category has consumed.</p></div><a class="btn btn-primary" href="#add-category"><i class="fa fa-plus"></i> Add category</a></div>
<div class="grid"><section class="card" id="add-category"><div class="card-head"><div><div class="card-title">Create a budget</div><div class="card-sub">Set a category limit before recording expenses.</div></div></div><form method="post"><input type="hidden" name="action" value="create"><div class="form-grid"><div class="form-group"><label>Category name</label><input class="form-control" name="expense_category_name" placeholder="e.g. Groceries" required></div><div class="form-group"><label>Budget amount (PKR)</label><input class="form-control" type="number" name="amount" min="0" step="0.01" placeholder="50000" required></div></div><div class="form-actions"><button class="btn btn-primary"><i class="fa fa-check"></i> Create budget</button></div></form></section>
<section class="hero"><h2>Keep spending intentional.</h2><p>Use category budgets as guardrails. Over-budget categories are automatically highlighted on the dashboard.</p><div class="hero-value">PKR <?= money(dashboard_stats($con)['balance']) ?></div><p>Current remaining budget</p></section></div>
<section class="card table-card"><div class="table-toolbar"><div><div class="card-title">All budget categories</div><div class="card-sub">Edit limits without losing transaction history.</div></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Category</th><th>Budget</th><th>Spent</th><th>Remaining</th><th>Usage</th><th>Action</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($rows)): $remain=(float)$r['amount']-(float)$r['spent'];$pct=$r['amount']?((float)$r['spent']/(float)$r['amount'])*100:0; ?><tr><td><strong><?= e($r['expense_category_name']) ?></strong></td><td>PKR <?= money($r['amount']) ?></td><td>PKR <?= money($r['spent']) ?></td><td class="<?= $remain<0?'kpi-negative':'kpi-positive' ?>"><strong>PKR <?= money($remain) ?></strong></td><td><span class="badge <?= $pct>100?'badge-red':($pct>=80?'badge-amber':'badge-green') ?>"><?= money($pct) ?>%</span></td><td><button class="btn btn-light" onclick='editCat(<?= json_encode($r,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT) ?>)'><i class="fa fa-pencil"></i> Edit</button></td></tr><?php endwhile; ?></tbody></table></div></section>
<div class="modal" id="editModal" style="display:none"><div class="modal-box"><div class="modal-head"><div><div class="card-title">Edit budget</div><div class="card-sub">Update the category name or spending limit.</div></div><button class="close" onclick="closeEdit()">&times;</button></div><form method="post"><input type="hidden" name="action" value="update"><input type="hidden" name="id" id="edit_id"><div class="form-grid"><div class="form-group"><label>Category name</label><input class="form-control" name="expense_category_name" id="edit_name" required></div><div class="form-group"><label>Budget amount (PKR)</label><input class="form-control" type="number" min="0" step="0.01" name="amount" id="edit_amount" required></div></div><div class="form-actions"><button class="btn btn-primary">Save changes</button></div></form></div></div>
<script>function editCat(x){document.getElementById('edit_id').value=x.expense_category_id;document.getElementById('edit_name').value=x.expense_category_name;document.getElementById('edit_amount').value=x.amount;document.getElementById('editModal').style.display='grid'}function closeEdit(){document.getElementById('editModal').style.display='none'}</script>
<?php render_footer(); ?>
